#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<int> to, cap;
    vector<vector<int>> graph(n + 1);
    for (const vector<long long>& e : edges) {
        graph[e[0]].push_back((int)to.size());
        to.push_back((int)e[1]);
        cap.push_back(1);
        graph[e[1]].push_back((int)to.size());
        to.push_back((int)e[0]);
        cap.push_back(1);
    }
    long long flow = 0;
    for (;;) {
        vector<int> via(n + 1, -1);
        vector<char> seen(n + 1, 0);
        seen[1] = 1;
        vector<int> queue = {1};
        for (size_t i = 0; i < queue.size() && !seen[n]; i++) {
            int x = queue[i];
            for (int e : graph[x]) {
                int y = to[e];
                if (cap[e] > 0 && !seen[y]) {
                    seen[y] = 1;
                    via[y] = e;
                    queue.push_back(y);
                }
            }
        }
        if (!seen[n]) break;
        int y = (int)n;
        while (y != 1) {
            int e = via[y];
            cap[e]--;
            cap[e ^ 1]++;
            y = to[e ^ 1];
        }
        flow++;
    }
    cout << flow << "\n";

    return 0;
}

