import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] to = new int[2 * edges.length];
        int[] cap = new int[2 * edges.length];
        int[] gHead = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            gHead[(int) edges[i][0] + 1]++;
            gHead[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= nodes; v++) gHead[v + 1] += gHead[v];
        int[] gSlot = new int[2 * edges.length];
        int[] gFill = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0], b = (int) edges[i][1];
            to[2 * i] = b;
            cap[2 * i] = 1;
            to[2 * i + 1] = a;
            cap[2 * i + 1] = 1;
            gSlot[gHead[a] + gFill[a]] = 2 * i;
            gFill[a]++;
            gSlot[gHead[b] + gFill[b]] = 2 * i + 1;
            gFill[b]++;
        }
        long flow = 0;
        int[] via = new int[nodes + 1];
        boolean[] seen = new boolean[nodes + 1];
        int[] queue = new int[nodes + 1];
        for (;;) {
            Arrays.fill(via, -1);
            Arrays.fill(seen, false);
            seen[1] = true;
            int qh = 0, qt = 0;
            queue[qt++] = 1;
            while (qh < qt && !seen[nodes]) {
                int x = queue[qh++];
                for (int k = gHead[x]; k < gHead[x + 1]; k++) {
                    int e = gSlot[k];
                    int y = to[e];
                    if (cap[e] > 0 && !seen[y]) {
                        seen[y] = true;
                        via[y] = e;
                        queue[qt++] = y;
                    }
                }
            }
            if (!seen[nodes]) break;
            int y = nodes;
            while (y != 1) {
                int e = via[y];
                cap[e]--;
                cap[e ^ 1]++;
                y = to[e ^ 1];
            }
            flow++;
        }
        System.out.println(flow);
    }
}
